select set_config('lumiscore.catalog_release_receipt','{"rows":[{"key":{"open_library_id":"OL792251A"},"seq":1,"relation":"authors","after_row":{"id":987340001,"name":"John Gardner","open_library_id":"OL792251A"},"before_row":null},{"key":{"open_library_id":"OL29542A"},"seq":2,"relation":"authors","after_row":{"id":987340002,"name":"Doreen Virtue","open_library_id":"OL29542A"},"before_row":null},{"key":{"native_identity_key":"nlscale:20261102:ol:OL719956W"},"seq":3,"relation":"works","after_row":{"id":987140001,"title":"Mammoet op zondag","cover_id":null,"author_id":969300006,"work_type":"collection","source_type":"open_library","open_library_id":"OL719956W","first_publish_year":1977,"native_identity_key":"nlscale:20261102:ol:OL719956W"},"before_row":null},{"key":{"open_library_edition_id":"OL4650339M"},"seq":4,"relation":"editions","after_row":{"id":987240001,"title":"Mammoet op zondag","isbn_10":null,"isbn_13":"9789029518697","work_id":987140001,"cover_id":null,"language":"dut","publisher":"De Arbeiderspers","publish_date":null,"open_library_edition_id":"OL4650339M"},"before_row":null},{"key":{"work_id":987140001,"language":"nl"},"seq":5,"relation":"catalog_work_descriptions","after_row":{"text":"De verhalen in deze bundel volgen een ik-figuur vanuit zijn gereformeerde jeugd naar zijn studententijd en het leven als volwassen wetenschapper. Herinneringen aan de omgeving waarin hij opgroeide staan naast ervaringen met werk, ontmoetingen en alledaagse verwachtingen. De afzonderlijke vertellingen hebben ieder een eigen situatie, maar zijn grotendeels in levensvolgorde gerangschikt. Maarten ’t Hart gebruikt herkenbare omstandigheden om te laten zien hoe iemand zijn plaats tussen anderen probeert te bepalen, zonder dat fictie daarmee een letterlijk autobiografisch verslag wordt.","work_id":987140001,"evidence":[{"note":"Eighteen-story original1977MammoetOpZondag, regularPaperbackISBN9789029518697. Individual limited linen variants and individual Avondwandeling are not t