nog onoverzichtelijker. Kruger zoekt naar een mogelijke dubbelagent binnen het netwerk dat hij zelf heeft opgebouwd. Zijn onderzoek draait daardoor niet alleen om geheime informatie, maar ook om de vraag wie hij nog kan vertrouwen.","work_id":987140002,"evidence":[{"note":"JohnGardner1926-2007 spy novelist, estate bibliography1980 original and exact Dutch DeWapentuin9789020409482/StefanVooren1982. Not same-name Americanliteraryauthor.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p82167112X"],"reference":"new-work-dossier-readings-041.json#157","checked_at":"2026-11-03T08:39:50.360Z"},{"type":"original_substantive_source_review","review":"content-amendment-019.json","sources":["https://john-gardner.com/the-complete-works/","https://openlibrary.org/books/OL32987186M/De_wapentuin","https://www.deboekenplank.nl/naslag/aut/g/gardner_j.htm","https://openlibrary.org/works/OL10587374W","https://data.bibliotheken.nl/id/nbt/p82167112X"]},{"type":"explicit_contributor_roles","credits":[],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"note":"Bound official bulk source reviewed once; no verified image available for import. Preserve resolver, inspect actual front/placeholder hosted. Do not infer Dutch absence.","type":"no_verified_cover_asset_retained","isbn13":"9789020409482","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":15115373,"receipt":"cover-archive-v2-readback.json","receiptSha256":"661d51a86f82f9bf19b025189d2de43e3566b0dd9dfadce9fed9bcb8e3c99a05"}],"checkedAt":"2026-11-03T08:39:50.359Z","editionKey":"/books/OL32987186M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://john-gardner.com/the-complete-works/","reviewed_at":"2026-11-03T0