innen de invloedssfeer van de baron. Bordewijk verbindt hun ontmoetingen met vragen over macht, bewondering en de prijs van een levenshouding die nauwelijks ruimte laat voor de zelfstandigheid van anderen.","work_id":987140006,"evidence":[{"note":"Apollyon1941, exact1978DutchHardcover9789023666486, Ewijk/Starnmeer notLeeuwenkuijl(EikenVanDodona). KBoriginal1941 overrides assumption1937.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p780222903"],"reference":"new-work-dossier-readings-041.json#175","checked_at":"2026-11-03T08:39:50.360Z"},{"type":"original_substantive_source_review","review":"content-amendment-017.json","sources":["https://www.dbnl.org/tekst/_ons003198301_01/_ons003198301_01_0116.php","https://www.dbnl.org/tekst/zuid004krit01_01/kll00059.php","https://openlibrary.org/works/OL14904141W","https://data.bibliotheken.nl/id/nbt/p780222903"]},{"type":"explicit_contributor_roles","credits":[],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"note":"Bound official bulk source reviewed once; no verified image available for import. Preserve resolver, inspect actual front/placeholder hosted. Do not infer Dutch absence.","type":"no_verified_cover_asset_retained","isbn13":"9789023666486","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":6451827,"receipt":"cover-archive-v2-readback.json","receiptSha256":"661d51a86f82f9bf19b025189d2de43e3566b0dd9dfadce9fed9bcb8e3c99a05"}],"checkedAt":"2026-11-03T08:39:50.360Z","editionKey":"/books/OL23959221M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://www.dbnl.org/tekst/_ons003198301_01/_ons003198301_01_0116.php","reviewed_at":"2026-11-03T08:39:50.36+00:00","source_name":"Gecontroleerde boek- en