ps://data.bibliotheken.nl/id/nbt/p780222903","review_batch":"nl-scale-20261102-041","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":947300704},"before_row":null},{"key":{"native_identity_key":"nlscale:20261102:ol:OL1667577W"},"seq":27,"relation":"works","after_row":{"id":987140007,"title":"Heden ik","cover_id":null,"author_id":987312004,"work_type":null,"source_type":"open_library","open_library_id":"OL1667577W","first_publish_year":1993,"native_identity_key":"nlscale:20261102:ol:OL1667577W"},"before_row":null},{"key":{"open_library_edition_id":"OL1502793M"},"seq":28,"relation":"editions","after_row":{"id":987240007,"title":"Heden ik","isbn_10":null,"isbn_13":"9789025402266","work_id":987140007,"cover_id":null,"language":"dut","publisher":"Contact","publish_date":null,"open_library_edition_id":"OL1502793M"},"before_row":null},{"key":{"work_id":987140007,"language":"nl"},"seq":29,"relation":"catalog_work_descriptions","after_row":{"text":"Renate Dorrestein beschrijft hoe ziekte haar vertrouwde leven onderbreekt. Werk, dagelijkse bezigheden en contact met anderen krijgen een andere betekenis wanneer haar lichaam niet meer doet wat zij verwacht. Haar zoektocht naar erkenning brengt ook de reacties van artsen en haar omgeving in beeld. In dit persoonlijke relaas over leven met ME onderzoekt zij wat er gebeurt met zelfstandigheid en zelfbeeld. Haar persoonlijke relaas laat zien hoe moeilijk het is uit te leggen wat voor de buitenwereld niet zichtbaar is.","work_id":987140007,"evidence":[{"note":"HedenIk1993, exactDutchPaperback9789025402266, Dorrestein literary illness memoir, notclinical instruction orfiction.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p104756799"],"reference":"new-work-dossier-readings-041.json#197","checked_at":"2026-11-03T08:39:50.360Z"},{"type":"original_substantive_source_review","review":"content-amendment-018.json","sources":["https://pure.uva.nl/ws/files/