n leek een veel gevaarlijker betekenis. Thea Beckman verbindt de ervaringen van Caspar met een stad waarin machthebbers belangstelling hebben voor geheimen die hun invloed verder kunnen vergroten.","work_id":987140009,"evidence":[{"note":"HetGeheimVanRotterdam1990, exactDutchHardcover9789060697757; current2005ISBNdifferent, content same historical novel. Publisher1991Kinderjury is readeraward notsales.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p061376841","https://data.bibliotheken.nl/id/nbt/p086526936"],"reference":"new-work-dossier-readings-041.json#201","checked_at":"2026-11-03T08:39:50.360Z"},{"type":"original_substantive_source_review","review":"content-amendment-018.json","sources":["https://lemniscaat.nl/boeken/het-geheim-van-rotterdam","https://lemniscaat.nl/bekroningen","https://data.bibliotheken.nl/id/nbt/p061376841","https://data.bibliotheken.nl/id/nbt/p086526936"]},{"type":"explicit_contributor_roles","credits":[],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"note":"Bound official bulk source reviewed once; no verified image available for import. Preserve resolver, inspect actual front/placeholder hosted. Do not infer Dutch absence.","type":"no_verified_cover_asset_retained","isbn13":"9789060697757","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":15176739,"receipt":"cover-archive-v2-readback.json","receiptSha256":"661d51a86f82f9bf19b025189d2de43e3566b0dd9dfadce9fed9bcb8e3c99a05"}],"checkedAt":"2026-11-03T08:39:50.360Z","editionKey":"/books/OL23085118M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://lemniscaat.nl/boeken/het-geheim-van-rotterdam","reviewed_at":"2026-11-03T08:39:50.36+00:00","source_name":"Gecontr